window.kbPageData["views/entry/k-6f2c19cca5f3e9da"] = {"key":"entry/k-6f2c19cca5f3e9da","state":{"route":"entry/k-6f2c19cca5f3e9da"},"node":{"id":"k-6f2c19cca5f3e9da","mode":"k","title":"三角形中位线","type":"原理与机制","domain":"数学","reading":"","intro":"","priority":100,"aliases":["三角形中位线平行于第三边且长度为第三边的一半","三角形中位线平行于第三边且长度为其一半"],"qs":["国考 2023 副省级 行测#64","国考 2024 副省级 行测#71"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":2,"repeatPositions":0,"directorySummary":"连接三角形两边中点的线段叫作三角形的中位线。中位线平行于第三边，长度等于第三边的一半。","review":{"definition":"连接三角形两边中点的线段叫作三角形的中位线。中位线平行于第三边，长度等于第三边的一半。","explanation":"在三角形AFC中，AE=EF、AD=DC，所以E、D分别是AF、AC的中点。由此得ED∥FC，且ED∶FC=1∶2。图中EC与FD交于O，利用平行线形成的等角和O处的对顶角，可判定三角形EOD与三角形COF相似，相似比为1∶2。","references":[],"evidence":"AE=EF=FB，AD=DC","disposition":"独立词条","basis":"据原题和解析编释。","title":"三角形中位线","related":[],"examFocus":{"国考 2023 副省级 行测#64":"利用边上的等分点识别三角形中位线，再借助相似三角形的边长与面积关系比较公园和人工湖的面积。","国考 2024 副省级 行测#71":"结合三角形中位线和各三角形、梯形等面积的条件，比较四角地砖的总面积与中央正方形的面积。"}},"readings":[{"origin":"k-6f2c19cca5f3e9da","title":"三角形中位线","qs":["国考 2023 副省级 行测#64"],"definition":"连接三角形两边中点的线段叫作三角形的中位线。中位线平行于第三边，长度等于第三边的一半。","explanation":"在三角形AFC中，AE=EF、AD=DC，所以E、D分别是AF、AC的中点。由此得ED∥FC，且ED∶FC=1∶2。图中EC与FD交于O，利用平行线形成的等角和O处的对顶角，可判定三角形EOD与三角形COF相似，相似比为1∶2。","evidence":"AE=EF=FB，AD=DC","doubt":"","references":[]},{"origin":"k-904e0ab6334ea1bb","title":"三角形中位线","qs":["国考 2024 副省级 行测#71"],"definition":"连接三角形两边中点的线段叫作三角形的中位线。它平行于第三边，长度等于第三边的一半。","explanation":"第71题中，按解析标记，BE、EC分别是相邻两个等腰梯形的一条腰。这两个梯形的腰分别与同一角部三角形的斜边相接，图示构型下 E 为 BC 的中点。过 E 作 EG 垂直于 AC，由于 AB 也垂直于 AC，EG 平行于 AB，因此 EG 是三角形 ABC 的中位线。取 EG＝1，便得到角部三角形的直角边 AB＝2。","evidence":"可知E为BC的中点，那么EG为等腰直角三角形ABC","doubt":"","references":[]}]},"questions":{"国考 2023 副省级 行测#64":{"paper":"国考 2023 副省级 行测","n":64,"mod":"数量关系","src":["503793642e845de9795f.pdf",12],"asrc":["ecade1ff5af69283232e.pdf",20],"card":"2e0de00cfb22e7971a29df45","links":[{"id":"k-6f2c19cca5f3e9da","role":"解题依据","why":"由两个中点确定ED为三角形AFC的中位线，为判定图中三角形相似提供平行条件。"}]},"国考 2024 副省级 行测#71":{"paper":"国考 2024 副省级 行测","n":71,"mod":"数量关系","src":["a566fec37e508ca7f975.pdf",13],"asrc":["a475ecf57d968bc14cd6.pdf",21],"card":"65f7d88efa9d71822a681752","links":[{"id":"k-6f2c19cca5f3e9da","role":"解题依据","why":"中位线与第三边的长度关系将所设的单位长度转化为角部三角形的直角边长。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-6f2c19cca5f3e9da":[["国考 2023 副省级 行测#64"],["国考 2024 副省级 行测#71"]]}};
